import{_ as s,c as n,o as t,j as m,Y as i,t as o}from"./chunks/framework.BNTND4LZ.js";const _=JSON.parse('{"title":"ipc_namespaces | x-cmd man (ip man7) | overview of Linux IPC namespaces","titleTemplate":false,"description":"x-cmd man (ip man7 Manual Page) | ipc_namespaces - overview of Linux IPC namespaces","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"ipc_namespaces | x-cmd man (ip man7) | overview of Linux IPC namespaces"}],["meta",{"name":"og:description","content":"x-cmd man (ip man7 Manual Page) | ipc_namespaces - overview of Linux IPC namespaces"}]]},"headers":[],"params":{"isMan":true,"man":"ipc_namespaces","category":"ip man7","desc":"overview of Linux IPC namespaces"},"relativePath":"ip/man7/ipc_namespaces.md","filePath":"ip/man7/[man].md"}'),r={name:"ip/man7/ipc_namespaces.md"},c={class:"visually-hidden"};function p(a,e,l,h,d,u){return t(),n("div",null,[m("h1",c,o(a.$params.man),1),e[0]||(e[0]=i('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>ipc_namespaces - overview of Linux IPC namespaces</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>IPC namespaces isolate certain IPC resources, namely, System V IPC objects (see <strong>sysvipc</strong>(7)) and (since Linux 2.6.30) POSIX message queues (see <strong>mq_overview</strong>(7)). The common characteristic of these IPC mechanisms is that IPC objects are identified by mechanisms other than filesystem pathnames.</p><p>Each IPC namespace has its own set of System V IPC identifiers and its own POSIX message queue filesystem. Objects created in an IPC namespace are visible to all other processes that are members of that namespace, but are not visible to processes in other IPC namespaces.</p><p>The following <em>/proc</em> interfaces are distinct in each IPC namespace:</p><ul><li><p>The POSIX message queue interfaces in <em>/proc/sys/fs/mqueue</em>.</p></li><li><p>The System V IPC interfaces in <em>/proc/sys/kernel</em>, namely: <em>msgmax</em>, <em>msgmnb</em>, <em>msgmni</em>, <em>sem</em>, <em>shmall</em>, <em>shmmax</em>, <em>shmmni</em>, and <em>shm_rmid_forced</em>.</p></li><li><p>The System V IPC interfaces in <em>/proc/sysvipc</em>.</p></li></ul><p>When an IPC namespace is destroyed (i.e., when the last process that is a member of the namespace terminates), all IPC objects in the namespace are automatically destroyed.</p><p>Use of IPC namespaces requires a kernel that is configured with the <strong>CONFIG_IPC_NS</strong> option.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>nsenter</strong>(1), <strong>unshare</strong>(1), <strong>clone</strong>(2), <strong>setns</strong>(2), <strong>unshare</strong>(2), <strong>mq_overview</strong>(7), <strong>namespaces</strong>(7), <strong>sysvipc</strong>(7)</p>',11))])}const P=s(r,[["render",p]]);export{_ as __pageData,P as default};
